         h(412) = h(411) + cdy*h(293)
         vbuf(170) = h(412)
         h(413) = g1(327) + cdz*g1(177)
         h(414) = h(413) + cdy*h(296)
         vbuf(171) = h(414)
         h(415) = g1(328) + cdz*g1(178)
