         vbuf(172) = h(416)
         h(417) = g1(329) + cdz*g1(179)
         h(418) = h(417) + cdy*h(302)
         vbuf(173) = h(418)
         h(419) = g1(330) + cdz*g1(180)
         h(420) = h(419) + cdy*h(305)
         vbuf(174) = h(420)
         h(421) = g1(335) + cdz*g1(185)
         h(422) = h(421) + cdy*h(308)
         vbuf(175) = h(422)
         h(423) = g1(336) + cdz*g1(186)
         h(424) = h(423) + cdy*h(311)
         vbuf(176) = h(424)
         h(425) = g1(337) + cdz*g1(187)
         h(426) = h(425) + cdy*h(314)
